export async function listTools() {
  return [
    {
      name: 'calculate',
      description: 'Perform a safe arithmetic calculation on two numbers.',
      inputSchema: {
        type: 'object',
        properties: {
          a: { type: 'number' },
          b: { type: 'number' },
          operation: { type: 'string', enum: ['add', 'subtract', 'multiply', 'divide'] }
        },
        required: ['a', 'b', 'operation']
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'calculate') {
    throw new Error(`Unknown tool: ${name}`);
  }

  // Check for missing fields
  if (args === null || typeof args !== 'object') {
    throw new Error('Invalid arguments');
  }
  const allowed = ['a', 'b', 'operation'];
  const keys = Object.keys(args);
  for (const k of allowed) {
    if (!(k in args)) {
      throw new Error(`Missing field: ${k}`);
    }
  }
  // Check for extra fields
  for (const k of keys) {
    if (!allowed.includes(k)) {
      throw new Error(`Unknown field: ${k}`);
    }
  }
  const { a, b, operation } = args;
  // Check numeric
  if (typeof a !== 'number' || Number.isNaN(a)) {
    throw new Error('a must be a number');
  }
  if (typeof b !== 'number' || Number.isNaN(b)) {
    throw new Error('b must be a number');
  }
  // Check operation
  const ops = ['add', 'subtract', 'multiply', 'divide'];
  if (!ops.includes(operation)) {
    throw new Error(`Unsupported operation: ${operation}`);
  }
  let result;
  switch (operation) {
    case 'add': result = a + b; break;
    case 'subtract': result = a - b; break;
    case 'multiply': result = a * b; break;
    case 'divide':
      if (b === 0) throw new Error('Division by zero');
      result = a / b;
      break;
  }
  return { content: [{ type: 'text', text: String(result) }] };
}
